// ── LLM Content Generation with Word-Count Enforcement (Groq) ─────────
// Calls Groq API up to 5 times until copy is strictly 90-150 words.
// Uses this.helpers.httpRequest() — the built-in n8n Code node HTTP helper.
//
// SETUP: Replace PASTE_YOUR_GROQ_API_KEY_HERE below with your actual key.
// Get a free key at: https://console.groq.com -> API Keys

const MODEL       = 'llama-3.3-70b-versatile';
const MIN_WORDS   = 90;
const MAX_WORDS   = 150;
const MAX_RETRIES = 5;

const topic        = $input.first().json.topic;
const scheduled_at = $input.first().json.scheduled_at;

const apiKey = 'PASTE_YOUR_GROQ_API_KEY_HERE'; // ← paste your Groq key here

if (!apiKey || apiKey === 'PASTE_YOUR_GROQ_API_KEY_HERE') {
  throw new Error('Replace the apiKey value with your real Groq API key from console.groq.com (starts with gsk_).');
}

const BASE_URL = 'https://api.groq.com/openai/v1/chat/completions';

const messages = [
  {
    role: 'system',
    content: `You are a professional social media copywriter. Write an engaging, brand-appropriate post. CRITICAL REQUIREMENT: Your response must be between ${MIN_WORDS} and ${MAX_WORDS} words — count your words before responding. Output ONLY the post text, no labels, hashtags, or metadata.`
  },
  {
    role: 'user',
    content: `Write a social media post about: ${topic}`
  }
];

let copy      = '';
let wordCount = 0;
let attempt   = 0;

while (attempt < MAX_RETRIES) {
  attempt++;

  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: BASE_URL,
    headers: {
      'Authorization': `Bearer ${apiKey}`,
      'Content-Type': 'application/json'
    },
    body: {
      model: MODEL,
      messages,
      max_tokens: 400,
      temperature: 0.7
    },
    json: true
  });

  copy      = response.choices[0].message.content.trim();
  wordCount = copy.split(/\s+/).filter(w => w.length > 0).length;

  if (wordCount >= MIN_WORDS && wordCount <= MAX_WORDS) {
    break;
  }

  if (attempt < MAX_RETRIES) {
    messages.push({ role: 'assistant', content: copy });
    messages.push({
      role: 'user',
      content: `Your previous draft was ${wordCount} words. Rewrite the full post to be between ${MIN_WORDS} and ${MAX_WORDS} words. Do not just trim — rewrite naturally so the post reads well and stays on topic.`
    });

    // Small delay to avoid rate limit on rapid retries
    await new Promise(resolve => setTimeout(resolve, 500));
  }
}

const withinRange = wordCount >= MIN_WORDS && wordCount <= MAX_WORDS;

if (!withinRange) {
  throw new Error(
    `Could not generate copy within ${MIN_WORDS}–${MAX_WORDS} words after ${attempt} attempts ` +
    `(last draft: ${wordCount} words). Workflow stopped — re-run to retry.`
  );
}

return [{
  json: {
    topic,
    scheduled_at,
    copy,
    wordCount,
    attempts: attempt,
    withinRange
  }
}];
